function buildStudentCourseGroups(instructorCourses, submissions, studentEmail = "2003988@eduflex.edu") {
    return instructorCourses.map((c)=>{
        const courseSubmissions = submissions.filter((s)=>s.courseCode === c.code);
        const mapItem = (item, itemType)=>{
            const sub = courseSubmissions.find((s)=>(s.itemId === item.id || s.itemTitle.toLowerCase() === item.title.toLowerCase()) && (!studentEmail || s.studentEmail === studentEmail));
            let status = "notStarted";
            if (sub) {
                status = "submitted";
            } else {
                const dueTime = new Date(item.due).getTime();
                const now = Date.now();
                if (!isNaN(dueTime)) {
                    const diffDays = (dueTime - now) / (1000 * 60 * 60 * 24);
                    if (diffDays < 0) {
                        status = "overdue";
                    } else if (diffDays <= 14) {
                        status = "dueSoon";
                    }
                }
            }
            return {
                id: item.id || `${itemType.toLowerCase()}-${item.title.toLowerCase().replace(/[^a-z0-9]/g, "-")}`,
                name: item.title,
                description: item.description || (itemType === "Assessment" ? "Major assessment milestone and project deliverable." : "Coursework and lab deliverable."),
                dueDate: item.due,
                status,
                score: sub?.score !== undefined ? `${sub.score}` : undefined,
                submissionDate: sub?.submittedAt,
                feedback: sub?.feedback,
                type: itemType,
                maxScore: item.maxScore ?? 100,
                weight: item.weight ?? (itemType === "Assessment" ? 25 : undefined)
            };
        };
        const publishedAssignments = (c.assignments || []).filter((a)=>a.status !== "Draft").map((a)=>mapItem(a, "Assignment"));
        const publishedAssessments = (c.assessments || []).filter((ass)=>ass.status === "Published" || !ass.status).map((ass)=>mapItem(ass, "Assessment"));
        return {
            code: c.code,
            title: c.name,
            term: c.term || "T226",
            iconColor: c.color,
            assignments: publishedAssignments,
            assessments: publishedAssessments
        };
    });
}
